INSERT INTO candidate_content (candidate_id, language, section_type, title, body_markdown, sort_order, review_status, reviewed_at, content_hash, source_revision, active)
SELECT c.candidate_id, 'ru', 'OVERVIEW', 'AI Overview', '**Бейбит Бахытович Алибеков** (род. 1984, Алматы) — казахстанский предприниматель, медиаменеджер, блогер и общественный деятель, сопредседатель партии *Respublica*.

### Основные направления деятельности
* **Медиа и блоги:** Руководитель медиахолдинга First Media Group, создатель ведущих автомобильных и бизнес-каналов в Казахстане с суммарной аудиторией свыше 850 000 подписчиков.
* **Бизнес и брендинг:** Основатель брендов одежды и аксессуаров (*Alibekov*, *ALLOFF*), издательских проектов и часовых коллабораций.
* **Политика и МСБ:** Сопредседатель партии *Respublica*, продвижение инициатив по развитию креативной индустрии, цифровизации и защите малого бизнеса.

### Общественная жизнь
Постоянный спикер казахстанских бизнес-форумов и подкастов, инициатор благотворительных аукционов и проектов по поддержке молодых предпринимателей.', 0, 'PUBLISHED', CURRENT_TIMESTAMP, 'eca981977e287e511d0deaa7cd4318cca468a9cf141e9d780a9c39ba281f64d6', 'google_ai_overview_search', TRUE
FROM candidate c
WHERE c.party_id = 'respublica' AND c.list_order = 1;

INSERT INTO candidate_content (candidate_id, language, section_type, title, body_markdown, sort_order, review_status, reviewed_at, content_hash, source_revision, active)
SELECT c.candidate_id, 'kk', 'OVERVIEW', 'AI Шолу', '**Бейбіт Бақытұлы Әлібеков** (1984 ж.т., Алматы) — қазақстандық кәсіпкер, медиаменеджер, блогер және қоғам қайраткері, *Respublica* партиясының тең төрағасы.

### Негізгі қызмет бағыттары
* **Медиа және блогерлік:** First Media Group медиахолдингінің басшысы, авто және бизнес бағытындағы танымал жобалардың авторы (850 000-нан астам желі оқырманы).
* **Бизнес және брендтер:** *Alibekov* және *ALLOFF* киім мен аксессуарлар брендтерінің, баспа жобалары мен мейрамхана бастамаларының негізін қалаушы.
* **Саясат және ШОБ:** *Respublica* партиясының тең төрағасы, креативті экономика мен шағын және орта бизнесті қолдауды ілгерілетуші.

### Қоғамдық белсенділік
Бизнес-форумдар мен подкасттардың тұрақты спикері, қайырымдылық акциялары мен жас кәсіпкерлерді қолдау жобаларының бастамашысы.', 0, 'PUBLISHED', CURRENT_TIMESTAMP, '1048d656f500aa1d14691d12e22dc8724a2049da1d1b989af116f7169c37a661', 'google_ai_overview_search', TRUE
FROM candidate c
WHERE c.party_id = 'respublica' AND c.list_order = 1;

