SELECT c.candidate_id, 'ru', 'OVERVIEW', 'AI Overview', '**Аубакиров Нурлан Ерикбаевич** (1975 г.р.) — казахстанский общественно-политический деятель, представитель партийного аппарата, кандидат в депутаты от партии «Respublica». Занимает должность: *председатель Карагандинского областного филиала партии «Respublica»*.

### Основные направления деятельности
* **Партийное строительство и работа с населением:** Организационно-политическая работа, координация региональных филиалов партии, проведение общественных приемных.
* **Региональное представительство:** Защита интересов жителей региона (Караганда) и участие в решении местных социально-экономических вопросов.
* **Партийная программа:** Продвижение инициатив партии «Respublica» по совершенствованию законодательства и поддержке граждан.

### Общественная жизнь
Принимает участие в общественной жизни региона, взаимодействует с избирателями и профессиональным сообществом.', 0, 'PUBLISHED', CURRENT_TIMESTAMP, 'e0a1374190a635096e728d1db17708e6cb413a8ddd878bc1cb744d1a3e867295', 'google_ai_overview_search', TRUE
FROM candidate c
WHERE c.party_id = 'respublica' AND c.list_order = 9;

INSERT INTO candidate_content (candidate_id, language, section_type, title, body_markdown, sort_order, review_status, reviewed_at, content_hash, source_revision, active)
SELECT c.candidate_id, 'kk', 'OVERVIEW', 'AI Шолу', '**Аубакиров Нурлан Ерикбаевич** (1975 ж.т.) — қазақстандық қоғамдық-саяси қайраткер, партиялық аппарат өкілі, «Respublica» партиясы атынан депутаттыққа үміткер. Қазіргі атқаратын лауазымы: *Respublica партиясының Қарағанды облыстық филиалының төрағасы*.

### Негізгі қызмет бағыттары
* **Партиялық құрылым және халықпен жұмыс:** Ұйымдастырушылық-саяси жұмыс, өңірлік партия филиалдарын үйлестіру және қоғамдық қабылдауларды өткізу.
* **Өңірлік өкілдік:** (Караганда) өңірі тұрғындарының мүдделерін қорғау және өзекті мәселелерді шешуге қатысу.
* **Партиялық бағдарлама:** «Respublica» партиясы сайлауалды бағдарламасын ілгерілету және халықтың әлеуметтік жағдайын жақсарту бастамалары.

### Қоғамдық белсенділік
Өңірдің қоғамдық өміріне белсене қатысады, сайлаушылармен және кәсіби қауымдастықпен тұрақты байланыс орнатқан.', 0, 'PUBLISHED', CURRENT_TIMESTAMP, '8ece2a95f938bd61ac05e9c59fb84960ef6ae2825de1793f576dd0dad290bc6a', 'google_ai_overview_search', TRUE
FROM candidate c
WHERE c.party_id = 'respublica' AND c.list_order = 9;

