### Негізгі қызмет бағыттары
* **Заң шығару және парламенттік қызмет:** Заң жобаларын әзірлеу мен сараптамаға қатысу, парламенттік бақылау және сайлаушылардың мүддесін қорғау.
* **Өңірлік өкілдік:** (Астана) өңірі тұрғындарының мүдделерін қорғау және өзекті мәселелерді шешуге қатысу.
* **Партиялық бағдарлама:** «Әділет» («AMANAT») партиясы сайлауалды бағдарламасын ілгерілету және халықтың әлеуметтік жағдайын жақсарту бастамалары.

### Қоғамдық белсенділік
Өңірдің қоғамдық өміріне белсене қатысады, сайлаушылармен және кәсіби қауымдастықпен тұрақты байланыс орнатқан.', 0, 'PUBLISHED', CURRENT_TIMESTAMP, '9f729b02d645271cdd5cc4f68141e7ba308bb47199e0ea60abbda95f59c82627', 'google_ai_overview_search', TRUE
